<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import PageHeading from '@/components/PageHeading.vue'
import RecordEditor from '@/components/RecordEditor.vue'
import DeleteRecord from '@/components/DeleteRecord.vue'
import { workspace, save } from '@/lib/workspace'
import { dateLabel, money, describeError } from '@/lib/domain'
import type { Entity, Kind, ProjectStatus } from '@/lib/types'
const route=useRoute(), project=computed(()=>workspace.data!.projects.find(p=>p.id===route.params.id)), editor=ref<{kind:Kind;record?:Entity}|null>(null), deleting=ref<{kind:Kind;record:Entity;label:string}|null>(null), busy=ref(''), error=ref('')
const tasks=computed(()=>workspace.data!.tasks.filter(t=>t.project_id===project.value?.id)), invoices=computed(()=>workspace.data!.invoices.filter(i=>i.project_id===project.value?.id))
async function change(kind:Kind, record:Entity, values:Record<string,unknown>) { busy.value=record.id;error.value='';try{await save(kind,{...record,...values},record)}catch(e){error.value=describeError(e)}finally{busy.value=''} }
function projectState(status:ProjectStatus){if(project.value)void change('project',project.value,{status})}
</script>
<template><template v-if="project"><RouterLink to="/today">Return to Today</RouterLink><PageHeading :title="project.name" :subtitle="workspace.data!.clients.find(c=>c.id===project!.client_id)?.name || ''"><button class="small" @click="editor={kind:'project',record:project}">Edit project</button><button class="small" :disabled="busy===project.id" @click="projectState(project.status==='active'?'completed':'active')">{{ project.status==='active'?'Complete project':'Reopen project' }}</button><button v-if="project.status!=='archived'" class="small" :disabled="busy===project.id" @click="projectState('archived')">Archive project</button></PageHeading><div class="detail-top"><span class="pill" :class="project.status">{{ project.status }}</span><span>{{ project.deadline ? 'Deadline: '+dateLabel(project.deadline) : 'No deadline set' }}</span></div><div v-if="project.status!=='active'" class="notice">Project-deadline reminders have stopped. Unresolved task follow-ups and unpaid invoices keep their own reminders.</div><p v-if="error" class="notice error" role="alert">{{ error }}</p><section class="panel record-panel"><div class="group-head"><h2>Tasks</h2><span class="count">{{ tasks.length }}</span><div class="actions"><button class="quiet small" @click="editor={kind:'task'}">Add task</button></div></div><div v-for="t in tasks" :key="t.id" class="detail-row"><div class="row-title">{{ t.title }}<small v-if="t.completed" class="success">Completed</small></div><div class="row-date">{{ t.followup_date ? dateLabel(t.followup_date) : 'No follow-up date' }}</div><div class="actions"><button class="small" :disabled="busy===t.id" @click="change('task',t,{completed:!t.completed})">{{ t.completed?'Reopen task':'Complete task' }}</button><button class="small quiet" @click="editor={kind:'task',record:t}">Edit</button><button class="small danger" @click="deleting={kind:'task',record:t,label:t.title}">Delete</button></div></div><p v-if="!tasks.length" class="section-note">Add a task and an optional date to follow up.</p></section><section class="panel record-panel"><div class="group-head"><h2>Invoices</h2><span class="count">{{ invoices.length }}</span><div class="actions"><button class="quiet small" @click="editor={kind:'invoice'}">Add invoice</button></div></div><div v-for="i in invoices" :key="i.id" class="detail-row"><div class="row-title">{{ i.reference }}<small>{{ money(i.amount,i.currency) }}</small></div><div class="row-date">Due {{ dateLabel(i.due_date) }}<small :class="{success:i.paid}">{{ i.paid?'Paid':'Unpaid' }}</small></div><div class="actions"><button class="small" :disabled="busy===i.id" @click="change('invoice',i,{paid:!i.paid})">{{ i.paid?'Mark unpaid':'Mark paid' }}</button><button class="small quiet" @click="editor={kind:'invoice',record:i}">Edit</button><button class="small danger" @click="deleting={kind:'invoice',record:i,label:i.reference}">Delete</button></div></div><p v-if="!invoices.length" class="section-note">Track the full amount of an invoice issued elsewhere.</p></section><RecordEditor v-if="editor" :kind="editor.kind" :record="editor.record" :parent="project.id" @close="editor=null" /><DeleteRecord v-if="deleting" v-bind="deleting" @close="deleting=null" /></template><div v-else class="empty"><h1>Project unavailable</h1><p>This project no longer exists or isn’t in your workspace.</p><RouterLink to="/projects">Browse your projects</RouterLink></div></template>
